import { Check, Sparkles } from 'lucide-react';
import { useId, useState, type ComponentProps, type CSSProperties, type ReactNode } from 'react';
import { cn } from '../lib/cn';
import { Button } from './button';
import { pluralRu } from './canvas-check';
import { Spinner } from './spinner';

/* ---------- Colours and placement ---------- */

/** Participant colour 1–3 (not accent, warning or danger); more people cycle through the three. */
export type PresenceSlot = number;

const fallbacks = ['oklch(0.56 0.2 320)', 'oklch(0.55 0.12 215)', 'oklch(0.55 0.14 135)'] as const;

/** CSS colour of a participant: the presence token, with the Paper value as a fallback until the token ships. */
export function presenceColor(slot: PresenceSlot): string {
  const index = (((Math.trunc(slot) - 1) % 3) + 3) % 3;
  return `var(--color-presence-${index + 1}, ${fallbacks[index]})`;
}

const presenceFg = 'var(--color-presence-fg, oklch(0.995 0 0))';

/** Ring of a step someone else has selected: their colour 2 + a 16 % halo. For the node card. */
export function presenceRing(slot: PresenceSlot): CSSProperties {
  const color = presenceColor(slot);
  return { boxShadow: `0 0 0 2px ${color}, 0 0 0 6px color-mix(in oklab, ${color} 16%, transparent)` };
}

interface Placed {
  /** Graph coordinates: with both set the element is absolutely positioned in the engine's graph layer. */
  x?: number;
  y?: number;
}

const place = ({ x, y }: Placed, style?: CSSProperties): CSSProperties | undefined =>
  x === undefined || y === undefined ? style : { position: 'absolute', left: x, top: y, ...style };

const initialsOf = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part.charAt(0).toUpperCase())
    .join('');

/* ---------- Presence ---------- */

/** «Анна и Игорь здесь», «Анна, Игорь и ещё 3 здесь». */
export function presenceLabel(names: readonly string[]): string {
  if (names.length <= 1) return `${names[0] ?? 'Никого'} здесь`;
  if (names.length <= 3) return `${names.slice(0, -1).join(', ')} и ${names.at(-1)} здесь`;
  return `${names.slice(0, 2).join(', ')} и ещё ${names.length - 2} здесь`;
}

export interface CanvasCollaborator {
  id: string;
  name: string;
  /** Colour slot 1–3; default — by position in the list. */
  presence?: PresenceSlot;
}

export interface CanvasPresenceProps extends ComponentProps<'div'> {
  people: readonly CanvasCollaborator[];
}

/** Capsule in the canvas corner: faces of the people here and their names. */
export function CanvasPresence({ people, className, ...props }: CanvasPresenceProps) {
  return (
    <div data-slot="canvas-presence" className={cn('inline-flex h-8 items-center gap-2 rounded-full bg-surface-1 pr-2.5 pl-1 shadow-[0_0_0_1px_var(--color-border)]', className)} {...props}>
      <span aria-hidden className="flex -space-x-1">
        {people.slice(0, 3).map((person, index) => {
          const color = presenceColor(person.presence ?? index + 1);
          return (
            <span
              key={person.id}
              className="grid size-6 place-items-center rounded-full text-[10px] font-bold text-fg-1 shadow-[0_0_0_2px_var(--color-surface-1)]"
              style={{ backgroundColor: `color-mix(in oklab, ${color} 22%, var(--color-surface-1))` }}
            >
              {initialsOf(person.name)}
            </span>
          );
        })}
      </span>
      <span className="text-caption text-fg-2">{presenceLabel(people.map((person) => person.name))}</span>
    </div>
  );
}

export interface CanvasCursorProps extends Omit<ComponentProps<'div'>, 'children'>, Placed {
  name: string;
  presence?: PresenceSlot;
}

/** Another person's pointer with their name; silent for screen readers — CanvasPresence says who is here. */
export function CanvasCursor({ name, presence = 1, x, y, className, style, ...props }: CanvasCursorProps) {
  const color = presenceColor(presence);
  return (
    <div
      aria-hidden
      data-slot="canvas-cursor"
      className={cn('pointer-events-none flex flex-col items-start gap-0.5 transition-[left,top] duration-(--duration-fast) ease-linear motion-reduce:transition-none', className)}
      style={place({ x, y }, style)}
      {...props}
    >
      <svg viewBox="0 0 24 24" className="size-[18px]">
        <path d="M4 3 20 11l-7 2-3 7L4 3Z" fill={color} stroke="var(--color-surface-1)" strokeWidth="1.5" strokeLinejoin="round" />
      </svg>
      <span className="flex h-5 items-center rounded-xs px-[7px] text-overline font-semibold whitespace-nowrap" style={{ backgroundColor: color, color: presenceFg }}>
        {name}
      </span>
    </div>
  );
}

export interface CanvasEditingLabelProps extends Omit<ComponentProps<'span'>, 'children'>, Placed {
  name: string;
  presence?: PresenceSlot;
}

/** «Игорь правит» over a step someone else has selected; the step is not locked. Pair with presenceRing. */
export function CanvasEditingLabel({ name, presence = 2, x, y, className, style, ...props }: CanvasEditingLabelProps) {
  return (
    <span
      data-slot="canvas-editing-label"
      className={cn('inline-flex h-5 items-center rounded-t-xs rounded-br-xs rounded-bl-[2px] px-[7px] text-overline font-semibold whitespace-nowrap', className)}
      style={place({ x, y }, { backgroundColor: presenceColor(presence), color: presenceFg, ...style })}
      {...props}
    >
      {name} правит
    </span>
  );
}

/* ---------- Sticky and comments ---------- */

export interface CanvasStickyProps extends ComponentProps<'div'>, Placed {
  author?: string;
  /** «2 мин назад». */
  time?: string;
  presence?: PresenceSlot;
}

/** Sticky note on the canvas: warning-soft, 200 wide, the author's initial in their colour. */
export function CanvasSticky({ author, time, presence = 1, x, y, className, style, children, ...props }: CanvasStickyProps) {
  return (
    <div
      role="note"
      data-slot="canvas-sticky"
      className={cn('flex w-[200px] flex-col gap-2 rounded-r-md rounded-tl-[4px] rounded-bl-md bg-warning-soft p-3 shadow-[0_1px_3px_color-mix(in_oklab,var(--color-fg-1)_8%,transparent)]', className)}
      style={place({ x, y }, style)}
      {...props}
    >
      <div className="text-body-xs text-fg-1">{children}</div>
      {author ? (
        <p className="flex items-center gap-1.5 text-overline font-medium text-warning-soft-fg">
          <span
            aria-hidden
            className="grid size-5 shrink-0 place-items-center rounded-full text-[10px] font-bold text-fg-1"
            style={{ backgroundColor: `color-mix(in oklab, ${presenceColor(presence)} 22%, transparent)` }}
          >
            {initialsOf(author).charAt(0)}
          </span>
          {[author, time].filter(Boolean).join(' · ')}
        </p>
      ) : null}
    </div>
  );
}

export interface CanvasCommentPinProps extends Omit<ComponentProps<'button'>, 'children'>, Placed {
  /** Author of the last comment: their initials and colour. */
  author: string;
  count?: number;
  presence?: PresenceSlot;
}

/** 30 pin next to a step that has a comment thread. */
export function CanvasCommentPin({ author, count = 1, presence = 1, x, y, className, style, ...props }: CanvasCommentPinProps) {
  return (
    <button
      type="button"
      data-slot="canvas-comment-pin"
      aria-label={`Комментарии: ${count}, последний от ${author}`}
      className={cn(
        'kv-pressable grid size-[30px] place-items-center rounded-t-[15px] rounded-br-[15px] rounded-bl-[3px] text-overline font-bold text-fg-1 shadow-[0_0_0_2px_var(--color-surface-1),0_2px_6px_color-mix(in_oklab,var(--color-fg-1)_14%,transparent)] [--kv-press-scale:var(--scale-press-icon)]',
        className,
      )}
      style={place({ x, y }, { backgroundColor: `color-mix(in oklab, ${presenceColor(presence)} 22%, var(--color-surface-1))`, ...style })}
      {...props}
    >
      {initialsOf(author)}
    </button>
  );
}

export interface CanvasComment {
  id: string;
  author: string;
  /** «10 мин назад». */
  time: string;
  text: ReactNode;
}

export interface CanvasCommentThreadProps extends Omit<ComponentProps<'section'>, 'children'>, Placed {
  /** «Комментарии к «Есть бюджет?»». */
  'aria-label': string;
  comments: readonly CanvasComment[];
  onReply?: (text: string) => void;
  /** «Решено» hides the pin. */
  onResolve?: () => void;
  /** Esc closes the thread. */
  onClose?: () => void;
}

/** Comment thread at a step: 290 wide, newest last, a reply field and «Решено». */
export function CanvasCommentThread({ comments, onReply, onResolve, onClose, x, y, className, style, onKeyDown, ...props }: CanvasCommentThreadProps) {
  const [draft, setDraft] = useState('');
  const fieldId = useId();
  const send = () => {
    const text = draft.trim();
    if (!text || !onReply) return;
    onReply(text);
    setDraft('');
  };
  return (
    <section
      data-slot="canvas-comment-thread"
      className={cn('flex w-[290px] flex-col rounded-[14px] bg-overlay shadow-[0_0_0_1px_var(--color-border),0_12px_32px_color-mix(in_oklab,var(--color-fg-1)_12%,transparent)]', className)}
      style={place({ x, y }, style)}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.key === 'Escape' && onClose && !event.defaultPrevented) {
          event.preventDefault();
          onClose();
        }
      }}
      {...props}
    >
      {comments.map((comment) => (
        <article key={comment.id} className="flex flex-col gap-1 border-b border-separator px-3.5 py-3">
          <p className="flex items-center gap-1.5">
            <span className="text-caption font-semibold text-fg-1">{comment.author}</span>
            <span className="text-overline text-fg-3">{comment.time}</span>
          </p>
          <div className="text-body-xs text-fg-1">{comment.text}</div>
        </article>
      ))}
      <div className="flex h-control-lg shrink-0 items-center gap-2 pr-2 pl-3.5">
        {onReply ? (
          <>
            <label htmlFor={fieldId} className="sr-only">
              Ответить
            </label>
            <input
              id={fieldId}
              value={draft}
              placeholder="Ответить…"
              onChange={(event) => setDraft(event.target.value)}
              onKeyDown={(event) => {
                if (event.key !== 'Enter' || event.nativeEvent.isComposing) return;
                event.preventDefault();
                send();
              }}
              className="min-w-0 flex-1 bg-transparent text-body-xs text-fg-1 outline-none placeholder:text-fg-3"
            />
          </>
        ) : (
          <span className="flex-1" />
        )}
        {onResolve ? (
          <Button variant="secondary" size="xs" onClick={onResolve}>
            Решено
          </Button>
        ) : null}
      </div>
    </section>
  );
}

/* ---------- Agent builds the graph ---------- */

const graphSize = (steps: number, edges: number) => `${steps} ${pluralRu(steps, ['шаг', 'шага', 'шагов'])} и ${edges} ${pluralRu(edges, ['связь', 'связи', 'связей'])}`;

/** Ghost step the agent proposes: accent 5 % with a dashed 55 % outline. For the node card. */
export const CANVAS_GHOST_CLASS = 'bg-[color-mix(in_oklab,var(--color-accent)_5%,var(--color-surface-1))] outline-dashed outline-1 outline-[color-mix(in_oklab,var(--color-accent)_55%,transparent)] shadow-none';

export interface CanvasAgentPromptProps extends Omit<ComponentProps<'div'>, 'children'>, Placed {
  /** The task in words, as the person wrote it. */
  text: ReactNode;
  status: 'building' | 'done';
  steps?: number;
  edges?: number;
}

/** The request to Норда on the canvas and how far the build got. */
export function CanvasAgentPrompt({ text, status, steps = 0, edges = 0, x, y, className, style, ...props }: CanvasAgentPromptProps) {
  return (
    <div
      data-slot="canvas-agent-prompt"
      data-status={status}
      className={cn('flex w-[400px] max-w-full gap-2.5 rounded-md bg-surface-1 p-3 shadow-[0_0_0_1px_var(--color-border),0_4px_12px_color-mix(in_oklab,var(--color-fg-1)_6%,transparent)]', className)}
      style={place({ x, y }, style)}
      {...props}
    >
      <span aria-hidden className="grid size-7 shrink-0 place-items-center rounded-full bg-[color-mix(in_oklab,var(--color-chart-7)_14%,transparent)] text-chart-7">
        <Sparkles className="size-3.5 stroke-2" />
      </span>
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        <div className="text-[13px]/[19px] text-fg-1">{text}</div>
        <p role="status" className="flex items-center gap-1.5 text-caption font-medium text-accent-soft-fg">
          {status === 'building' ? <Spinner size={16} className="size-3 text-accent" /> : <Check aria-hidden className="size-3 stroke-[3] text-success-soft-fg" />}
          {status === 'building' ? 'Собираю граф…' : `Готово · ${graphSize(steps, edges)}`}
        </p>
      </div>
    </div>
  );
}

export interface CanvasAgentProposalProps extends Omit<ComponentProps<'section'>, 'children'> {
  steps: number;
  edges: number;
  /** Everything goes in as one history entry from Норда. */
  onAccept: () => void;
  /** Walk the ghosts one by one. */
  onStepwise?: () => void;
  onReject: () => void;
}

/** Bar under the ghost steps: accept all, one by one, or reject. */
export function CanvasAgentProposal({ steps, edges, onAccept, onStepwise, onReject, className, ...props }: CanvasAgentProposalProps) {
  const label = `Норда предлагает ${graphSize(steps, edges)}`;
  return (
    <section
      data-slot="canvas-agent-proposal"
      aria-label={label}
      className={cn('flex h-12 items-center justify-between gap-3 rounded-md bg-surface-1 pr-1.5 pl-4 shadow-[0_0_0_1px_var(--color-border),0_8px_24px_color-mix(in_oklab,var(--color-fg-1)_10%,transparent)]', className)}
      {...props}
    >
      <p className="truncate text-body-xs font-medium text-fg-1">{label}</p>
      <div className="flex shrink-0 gap-1.5">
        <Button variant="ghost" size="sm" onClick={onReject}>
          Отклонить
        </Button>
        {onStepwise ? (
          <Button variant="secondary" size="sm" onClick={onStepwise}>
            По одному
          </Button>
        ) : null}
        <Button size="sm" onClick={onAccept}>
          Принять всё
        </Button>
      </div>
    </section>
  );
}

import type { CanvasEdge, CanvasGraph, CanvasNode, CanvasPort, CanvasPortType } from './canvas-types';

/* ---------- Graph check ---------- */

export type CanvasProblemSeverity = 'error' | 'warning';

export type CanvasProblemKind = 'no-trigger' | 'cycle' | 'required-input' | 'unreachable' | 'open-branch' | 'broken-edge' | 'type-mismatch';

export interface CanvasProblem {
  /** Stable between runs of the same graph: kind plus the ids involved. */
  id: string;
  kind: CanvasProblemKind;
  /** error blocks publishing, warning does not. */
  severity: CanvasProblemSeverity;
  /** «Цикл без выхода». */
  title: string;
  /** What is wrong and how to fix it, with step names. */
  description: string;
  /** Steps to show: the first one gets the camera. */
  nodeIds: readonly string[];
  edgeId?: string;
  portId?: string;
}

export interface CheckGraphOptions<TData> {
  /** Step name in the messages; default — the node id. */
  label?: (node: CanvasNode<TData>) => string;
  /** Inputs that must be connected; default — ports marked `required`, the same ones the canvas draws in danger. */
  isRequired?: (node: CanvasNode<TData>, port: CanvasPort) => boolean;
}

/** Notes and groups are not steps: they never run and need no connections. */
const isStep = (node: CanvasNode<unknown>) => node.kind !== 'note' && node.kind !== 'group';

const typeNames: Record<CanvasPortType, string> = {
  flow: 'поток',
  text: 'текст',
  number: 'число',
  date: 'дата',
  boolean: 'да/нет',
  object: 'объект',
  list: 'список',
  tool: 'инструмент',
  memory: 'память',
  knowledge: 'знания',
};

/** Russian name of a port type: «текст», «число». */
export function portTypeName(type: CanvasPortType): string {
  return typeNames[type];
}

const capitalize = (text: string) => text.charAt(0).toUpperCase() + text.slice(1);

const plurals = new Intl.PluralRules('ru');

/** Russian noun for a count: `pluralRu(2, ['ошибка', 'ошибки', 'ошибок'])` → «ошибки». */
export function pluralRu(count: number, [one, few, many]: readonly [one: string, few: string, many: string]): string {
  const rule = plurals.select(count);
  return rule === 'one' ? one : rule === 'few' ? few : many;
}

// Anything becomes text without loss, so number, date and yes/no flow into text silently.
const intoText: ReadonlySet<CanvasPortType> = new Set(['number', 'date', 'boolean']);

function compatibility(from: CanvasPortType | undefined, to: CanvasPortType | undefined): 'ok' | 'convert' | 'wrong' {
  if (!from || !to || from === to) return 'ok';
  if (from === 'flow' || to === 'flow') return 'wrong';
  if (to === 'text' && intoText.has(from)) return 'ok';
  return 'convert';
}

/** Strongly connected components (Tarjan), each in discovery order. */
function components(ids: readonly string[], next: ReadonlyMap<string, readonly string[]>): string[][] {
  const index = new Map<string, number>();
  const low = new Map<string, number>();
  const stack: string[] = [];
  const onStack = new Set<string>();
  const result: string[][] = [];
  let counter = 0;

  const visit = (id: string) => {
    index.set(id, counter);
    low.set(id, counter);
    counter += 1;
    stack.push(id);
    onStack.add(id);
    for (const target of next.get(id) ?? []) {
      if (!index.has(target)) {
        visit(target);
        low.set(id, Math.min(low.get(id) ?? 0, low.get(target) ?? 0));
      } else if (onStack.has(target)) {
        low.set(id, Math.min(low.get(id) ?? 0, index.get(target) ?? 0));
      }
    }
    if (low.get(id) !== index.get(id)) return;
    const component: string[] = [];
    let member: string | undefined;
    do {
      member = stack.pop();
      if (member === undefined) break;
      onStack.delete(member);
      component.push(member);
    } while (member !== id);
    result.push(component);
  };

  for (const id of ids) if (!index.has(id)) visit(id);
  return result;
}

/** One loop through the component from its first step, to name it «А → Б → А». */
function loopPath(start: string, members: ReadonlySet<string>, next: ReadonlyMap<string, readonly string[]>): string[] {
  const path: string[] = [];
  const seen = new Set<string>();
  const walk = (id: string): boolean => {
    path.push(id);
    seen.add(id);
    for (const target of next.get(id) ?? []) {
      if (target === start) return true;
      if (members.has(target) && !seen.has(target) && walk(target)) return true;
    }
    path.pop();
    return false;
  };
  walk(start);
  return path;
}

/**
 * Finds what breaks a run before it starts: cycles with no way out, empty required inputs, steps the trigger never
 * reaches, branches left open after a fork, edges to missing ports and data of the wrong type. Errors come first.
 */
export function checkGraph<TData>(graph: CanvasGraph<TData>, options: CheckGraphOptions<TData> = {}): CanvasProblem[] {
  const { label = (node: CanvasNode<TData>) => node.id, isRequired = (_node: CanvasNode<TData>, port: CanvasPort) => port.required === true } = options;
  const problems: CanvasProblem[] = [];
  const steps = graph.nodes.filter((node) => isStep(node) && !node.disabled);
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const name = (id: string) => {
    const node = byId.get(id);
    return node ? label(node) : id;
  };
  const portOf = (node: CanvasNode<TData> | undefined, id: string) => node?.ports.find((port) => port.id === id);

  // Edges that point at real ports in the right direction; the rest are broken.
  const edges: CanvasEdge[] = [];
  for (const edge of graph.edges) {
    const source = portOf(byId.get(edge.source), edge.sourcePort);
    const target = portOf(byId.get(edge.target), edge.targetPort);
    if (source?.direction === 'out' && target?.direction === 'in') {
      edges.push(edge);
      continue;
    }
    problems.push({
      id: `broken-edge:${edge.id}`,
      kind: 'broken-edge',
      severity: 'error',
      title: 'Связь никуда не ведёт',
      description: `Связь «${name(edge.source)}» → «${name(edge.target)}» держится за порт, которого нет. Удалите её и протяните заново.`,
      nodeIds: [edge.source, edge.target].filter((id) => byId.has(id)),
      edgeId: edge.id,
    });
  }

  const next = new Map<string, string[]>();
  for (const edge of edges) next.set(edge.source, [...(next.get(edge.source) ?? []), edge.target]);

  if (steps.length && !steps.some((node) => node.kind === 'trigger')) {
    problems.push({
      id: 'no-trigger',
      kind: 'no-trigger',
      severity: 'error',
      title: 'Нет триггера',
      description: 'Граф ничто не запускает. Добавьте триггер: сообщение, расписание или вебхук.',
      nodeIds: [],
    });
  }

  for (const component of components(
    steps.map((node) => node.id),
    next,
  )) {
    const members = new Set(component);
    const [only] = component;
    if (component.length === 1 && only !== undefined && !(next.get(only) ?? []).includes(only)) continue;
    const exits = component.some((id) => {
      const kind = byId.get(id)?.kind;
      return (kind === 'condition' || kind === 'loop') && (next.get(id) ?? []).some((target) => !members.has(target));
    });
    if (exits) continue;
    const first = steps.find((node) => members.has(node.id))?.id ?? component[0] ?? '';
    const path = loopPath(first, members, next);
    const ordered = [...path, ...component.filter((id) => !path.includes(id))];
    problems.push({
      id: `cycle:${[...component].sort().join(',')}`,
      kind: 'cycle',
      severity: 'error',
      title: 'Цикл без выхода',
      description: `${[...path, first].map(name).join(' → ')}. Добавьте условие, которое выводит из цикла, например «не больше 3 раз».`,
      nodeIds: ordered,
    });
  }

  for (const node of steps) {
    for (const port of node.ports) {
      if (port.direction !== 'in' || !isRequired(node, port)) continue;
      if (edges.some((edge) => edge.target === node.id && edge.targetPort === port.id)) continue;
      problems.push({
        id: `required-input:${node.id}:${port.id}`,
        kind: 'required-input',
        severity: 'error',
        title: 'Пустой обязательный вход',
        description: `«${label(node)}» ждёт «${port.label ?? port.id}», но к нему ничего не подключено.`,
        nodeIds: [node.id],
        portId: port.id,
      });
    }
  }

  const triggers = steps.filter((node) => node.kind === 'trigger');
  if (triggers.length) {
    const reached = new Set<string>();
    const queue = triggers.map((node) => node.id);
    for (let id = queue.shift(); id !== undefined; id = queue.shift()) {
      if (reached.has(id)) continue;
      reached.add(id);
      queue.push(...(next.get(id) ?? []));
    }
    for (const node of steps) {
      if (reached.has(node.id)) continue;
      problems.push({
        id: `unreachable:${node.id}`,
        kind: 'unreachable',
        severity: 'warning',
        title: 'Шаг не запустится',
        description: `До «${label(node)}» не доходит ни одна связь от триггера. Подключите его или удалите.`,
        nodeIds: [node.id],
      });
    }
  }

  for (const node of steps) {
    const outs = node.ports.filter((port) => port.direction === 'out' && (port.type ?? 'flow') === 'flow');
    if (outs.length < 2) continue;
    const used = outs.filter((port) => edges.some((edge) => edge.source === node.id && edge.sourcePort === port.id));
    if (!used.length) continue;
    for (const port of outs) {
      if (used.includes(port)) continue;
      problems.push({
        id: `open-branch:${node.id}:${port.id}`,
        kind: 'open-branch',
        severity: 'warning',
        title: 'Ветка обрывается',
        description: `У «${label(node)}» ветка «${port.label ?? port.id}» никуда не ведёт — этот случай останется без действия.`,
        nodeIds: [node.id],
        portId: port.id,
      });
    }
  }

  for (const edge of edges) {
    const from = portOf(byId.get(edge.source), edge.sourcePort)?.type;
    const to = portOf(byId.get(edge.target), edge.targetPort);
    const verdict = compatibility(from, to?.type);
    if (verdict === 'ok' || !from || !to?.type) continue;
    const wrong = verdict === 'wrong';
    problems.push({
      id: `type-mismatch:${edge.id}`,
      kind: 'type-mismatch',
      severity: wrong ? 'error' : 'warning',
      title: wrong ? 'Данные вместо шага' : `${capitalize(typeNames[from])} идёт в ${typeNames[to.type]}`,
      description: wrong
        ? `Связь «${name(edge.source)}» → «${name(edge.target)}» соединяет порядок шагов с данными. Подключите её к порту того же вида.`
        : `«${to.label ?? to.id}» получает ${typeNames[from]} — вставить конвертер «${typeNames[from]} → ${typeNames[to.type]}»?`,
      nodeIds: [edge.target, edge.source],
      edgeId: edge.id,
      portId: to.id,
    });
  }

  // Array#sort is stable: within a severity the order of discovery stays.
  return problems.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'error' ? -1 : 1));
}

/* ---------- Version diff ---------- */

export interface CanvasGraphDiff {
  nodes: { added: string[]; changed: string[]; removed: string[]; unchanged: string[] };
  edges: { added: string[]; removed: string[] };
}

export interface DiffGraphsOptions<TData> {
  /** Whether a step stayed the same; default compares kind, ports, parent, flags and data deeply. */
  same?: (before: CanvasNode<TData>, after: CanvasNode<TData>) => boolean;
}

function deepEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) return false;
  if (a instanceof Date || b instanceof Date) return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keysA = Object.keys(a).filter((key) => (a as Record<string, unknown>)[key] !== undefined);
  const keysB = Object.keys(b).filter((key) => (b as Record<string, unknown>)[key] !== undefined);
  return keysA.length === keysB.length && keysA.every((key) => deepEqual((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key]));
}

// Position, size, selection and run status are view state: moving a step is not an edit of the automation.
const meaning = <TData>({ kind, ports, parentId, disabled, collapsed, data }: CanvasNode<TData>) => ({ kind, ports, parentId, disabled, collapsed, data });

/** What changed between two versions: steps added, changed, removed; edges added and removed. */
export function diffGraphs<TData>(before: CanvasGraph<TData>, after: CanvasGraph<TData>, options: DiffGraphsOptions<TData> = {}): CanvasGraphDiff {
  const { same = (a: CanvasNode<TData>, b: CanvasNode<TData>) => deepEqual(meaning(a), meaning(b)) } = options;
  const old = new Map(before.nodes.map((node) => [node.id, node]));
  const fresh = new Set(after.nodes.map((node) => node.id));
  const diff: CanvasGraphDiff = { nodes: { added: [], changed: [], removed: [], unchanged: [] }, edges: { added: [], removed: [] } };
  for (const node of after.nodes) {
    const previous = old.get(node.id);
    if (!previous) diff.nodes.added.push(node.id);
    else if (same(previous, node)) diff.nodes.unchanged.push(node.id);
    else diff.nodes.changed.push(node.id);
  }
  diff.nodes.removed = before.nodes.filter((node) => !fresh.has(node.id)).map((node) => node.id);
  const key = (edge: CanvasEdge) => `${edge.source}\u0000${edge.sourcePort}\u0000${edge.target}\u0000${edge.targetPort}`;
  const oldEdges = new Set(before.edges.map(key));
  const newEdges = new Set(after.edges.map(key));
  diff.edges.added = after.edges.filter((edge) => !oldEdges.has(key(edge))).map((edge) => edge.id);
  diff.edges.removed = before.edges.filter((edge) => !newEdges.has(key(edge))).map((edge) => edge.id);
  return diff;
}

// Graph model shared by the canvas engine, node cards, editor chrome and graph checks.

export type CanvasNodeKind = 'trigger' | 'action' | 'condition' | 'loop' | 'wait' | 'agent' | 'data' | 'group' | 'note';

/** Run state of a step or an edge: waiting → running → done | error; warning is a config problem before any run. */
export type CanvasRunStatus = 'idle' | 'waiting' | 'running' | 'done' | 'error' | 'warning' | 'skipped';

export type CanvasPortSide = 'top' | 'right' | 'bottom' | 'left';

export type CanvasPortDirection = 'in' | 'out';

/** flow carries the order of steps; the rest carry data and are coloured by type. */
export type CanvasPortType = 'flow' | 'text' | 'number' | 'date' | 'boolean' | 'object' | 'list' | 'tool' | 'memory' | 'knowledge';

export type CanvasEdgePath = 'bezier' | 'smoothstep' | 'step' | 'straight' | 'orthogonal';

export interface CanvasPoint {
  x: number;
  y: number;
}

/** x/y is the screen offset of the graph origin, zoom is the scale. */
export interface CanvasViewport {
  x: number;
  y: number;
  zoom: number;
}

export interface CanvasPort {
  id: string;
  side: CanvasPortSide;
  direction: CanvasPortDirection;
  type?: CanvasPortType;
  label?: string;
  /** More than one edge may attach; outputs default to true, inputs to false. */
  multiple?: boolean;
  /** Centre along the side in px from the node's top (left/right) or left edge (top/bottom); default: spread evenly. */
  offset?: number;
  /** An input the step cannot run without: drawn in danger while nothing is connected. */
  required?: boolean;
}

export interface CanvasNode<TData = unknown> {
  id: string;
  kind: CanvasNodeKind;
  /** Top-left corner in graph coordinates; relative to the parent group when parentId is set. */
  position: CanvasPoint;
  width?: number;
  height?: number;
  ports: readonly CanvasPort[];
  parentId?: string;
  selected?: boolean;
  collapsed?: boolean;
  disabled?: boolean;
  status?: CanvasRunStatus;
  /** Size handles when selected; default: groups and notes (steps keep a fixed width). */
  resizable?: boolean;
  data: TData;
}

export interface CanvasEdge {
  id: string;
  source: string;
  sourcePort: string;
  target: string;
  targetPort: string;
  path?: CanvasEdgePath;
  label?: string;
  status?: CanvasRunStatus;
  selected?: boolean;
}

export interface CanvasGraph<TData = unknown> {
  nodes: readonly CanvasNode<TData>[];
  edges: readonly CanvasEdge[];
}

/** An edge before it has an id: what a drag from port to port proposes. */
export interface CanvasConnection {
  source: string;
  sourcePort: string;
  target: string;
  targetPort: string;
}

/** select is not an edit: history replaces the present instead of adding a step. add and update come from the editor around the canvas. */
export type CanvasChangeType = 'select' | 'move' | 'resize' | 'connect' | 'reconnect' | 'delete' | 'paste' | 'layout' | 'label' | 'add' | 'update';

/** Why the graph changed; history uses it to merge and skip steps. */
export interface CanvasChange {
  type: CanvasChangeType;
  nodeIds?: readonly string[];
  edgeIds?: readonly string[];
  /** Changes with the same key in a row within a second are one history step (arrow-key nudges). */
  mergeKey?: string;
}
